extra.raw_output:
1://! `hof_game` — the scaffolded Bevy 0.19.1 game.
2://!
3://! This file is the **same binary in both modes** (PRD §3-C1): with
4://! `HOF_GAME_HEADLESS` set it runs with no window and no render world, and
5://! without it, it opens one real window.  Every round of the pipeline runs it
6://! headless, because SPIKE-2 measured windowed mode at 4.0 FPS on this machine,
7://! which is far too slow to observe a jump arc.
8://!
9://! Three facts from the spike reports are load-bearing here and must not be
10://! "tidied away":
11://!
12://! 1. **`ScheduleRunnerPlugin` is mandatory in headless mode.**  Without it the
13://!    app runs one frame and exits with code 0, and the BRP endpoint is never
14://!    bound (SPIKE-2 C7).
15://! 2. **`WgpuSettings { backends: None }` means "no render world at all"**, not
16://!    "an empty one": Bevy never adds `ExtractPlugin`, so port 15703 does not
17://!    exist.  The adapter depends on 15702 only.
18://! 3. **The observation surface is declared, not inferred.**  `RemotePlugin` +
19://!    `RemoteHttpPlugin` open 15702 on loopback with no authentication, which is
20://!    why this build exists for development and CI only.
22:use std::time::Duration;
24:use bevy::app::ScheduleRunnerPlugin;
25:use bevy::prelude::*;
26:use bevy::remote::{http::RemoteHttpPlugin, RemotePlugin};
27:use bevy::render::{settings::WgpuSettings, RenderPlugin};
28:use bevy::window::ExitCondition;
29:use bevy::winit::WinitPlugin;
31:mod contract;
32:mod game;
34:fn main() {
35:    let headless = headless_requested();
37:    let mut window_plugin = WindowPlugin::default();
38:    let render_plugin = if headless {
39:        window_plugin.primary_window = None;
40:        window_plugin.exit_condition = ExitCondition::DontExit;
41:        window_plugin.close_when_requested = false;
42:        RenderPlugin {
43:            render_creation: WgpuSettings {
44:                backends: None,
45:                ..default()
46:            }
47:            .into(),
48:            ..default()
49:        }
50:    } else {
51:        RenderPlugin::default()
52:    };
53:    let builder = DefaultPlugins.set(window_plugin).set(render_plugin);
55:    let mut app = App::new();
56:    if headless {
57:        app.add_plugins(builder.build().disable::<WinitPlugin>());
58:        // Without this the process would run a single frame and exit.
59:        app.add_plugins(ScheduleRunnerPlugin::run_loop(Duration::from_secs_f64(
60:            1.0 / 60.0,
61:        )));
62:    } else {
63:        app.add_plugins(builder);
64:    }
66:    // The observation surface.  Same binary, both modes.
67:    app.add_plugins((RemotePlugin::default(), RemoteHttpPlugin::default()));
69:    app.init_resource::<contract::CoinCounter>()
70:        .init_resource::<contract::WinFlag>()
71:        .init_resource::<contract::FrameCounter>()
72:        .init_resource::<contract::InputIntent>()
73:        // Round-2 repair: the launch nonce is *this process's own* value, so it
74:        // is inserted rather than defaulted — `init_resource` would install the
75:        // empty default and every readiness check would fail.
76:        .insert_resource(contract::ProcessNonce::from_env());
77:    contract::register(&mut app);
78:    game::add(&mut app);
80:    watch_stdin();
81:    app.run();
82:}
84:/// The runtime switch: set (to anything but `0`) means headless.
85:fn headless_requested() -> bool {
86:    match std::env::var(contract::HEADLESS_ENV) {
87:        Ok(value) => value != "0",
88:        Err(_) => false,
89:    }
90:}
92:/// Exit the process when the launcher writes `quit` on stdin.
93:///
94:/// The launcher asks politely before it kills, and a game that ignored the line
95:/// would pay the full termination grace on every stop.  This is deliberately a
96:/// raw thread rather than a Bevy event: it must work in both the windowed and
97:/// the headless configuration, and it needs nothing from the ECS.
98:fn watch_stdin() {
99:    use std::io::BufRead;
100:    std::thread::spawn(|| {
101:        let stdin = std::io::stdin();
102:        for line in stdin.lock().lines() {
103:            match line {
104:                Ok(line) if line.trim() == "quit" => std::process::exit(0),
105:                Ok(_) => {}
106:                // EOF: the launcher closed the pipe without asking us to stop.
107:                Err(_) => break,
108:            }
109:        }
110:    });
111:}

