1: //! `hof_game` 鈥?the scaffolded Bevy 0.19.1 game.
2: //!
3: //! This file is the **same binary in both modes** (PRD 搂3-C1): with
4: //! `HOF_GAME_HEADLESS` set it runs with no window and no render world, and
5: //! without it, it opens one real window.  Every round of the pipeline runs it
6: //! headless, because SPIKE-2 measured windowed mode at 4.0 FPS on this machine,
7: //! which is far too slow to observe a jump arc.
8: //!
9: //! Three facts from the spike reports are load-bearing here and must not be
10: //! "tidied away":
11: //!
12: //! 1. **`ScheduleRunnerPlugin` is mandatory in headless mode.**  Without it the
13: //!    app runs one frame and exits with code 0, and the BRP endpoint is never
14: //!    bound (SPIKE-2 C7).
15: //! 2. **`WgpuSettings { backends: None }` means "no render world at all"**, not
16: //!    "an empty one": Bevy never adds `ExtractPlugin`, so port 15703 does not
17: //!    exist.  The adapter depends on 15702 only.
18: //! 3. **The observation surface is declared, not inferred.**  `RemotePlugin` +
19: //!    `RemoteHttpPlugin` open 15702 on loopback with no authentication, which is
20: //!    why this build exists for development and CI only.
21: 
22: use std::time::Duration;
23: 
24: use bevy::app::ScheduleRunnerPlugin;
25: use bevy::prelude::*;
26: use bevy::remote::{http::RemoteHttpPlugin, RemotePlugin};
27: use bevy::render::{settings::WgpuSettings, RenderPlugin};
28: use bevy::window::ExitCondition;
29: use bevy::winit::WinitPlugin;
30: 
31: mod contract;
32: mod game;
33: #[cfg(test)]
34: mod sim_tests;
35: 
36: fn main() {
37:     let headless = headless_requested();
38: 
39:     let mut window_plugin = WindowPlugin::default();
40:     let render_plugin = if headless {
41:         window_plugin.primary_window = None;
42:         window_plugin.exit_condition = ExitCondition::DontExit;
43:         window_plugin.close_when_requested = false;
44:         RenderPlugin {
45:             render_creation: WgpuSettings {
46:                 backends: None,
47:                 ..default()
48:             }
49:             .into(),
50:             ..default()
51:         }
52:     } else {
53:         RenderPlugin::default()
54:     };
55:     let builder = DefaultPlugins.set(window_plugin).set(render_plugin);
56: 
57:     let mut app = App::new();
58:     if headless {
59:         app.add_plugins(builder.build().disable::<WinitPlugin>());
60:         // Without this the process would run a single frame and exit.
61:         app.add_plugins(ScheduleRunnerPlugin::run_loop(Duration::from_secs_f64(
62:             1.0 / 60.0,
63:         )));
64:     } else {
65:         app.add_plugins(builder);
66:     }
67: 
68:     // The observation surface.  Same binary, both modes.
69:     app.add_plugins((RemotePlugin::default(), RemoteHttpPlugin::default()));
70: 
71:     app.init_resource::<contract::CoinCounter>()
72:         .init_resource::<contract::WinFlag>()
73:         .init_resource::<contract::FrameCounter>()
74:         .init_resource::<contract::InputIntent>()
75:         // Round-2 repair: the launch nonce is *this process's own* value, so it
76:         // is inserted rather than defaulted 鈥?`init_resource` would install the
77:         // empty default and every readiness check would fail.
78:         .insert_resource(contract::ProcessNonce::from_env());
79:     contract::register(&mut app);
80:     game::add(&mut app);
81: 
82:     watch_stdin();
83:     app.run();
84: }
85: 
86: /// The runtime switch: set (to anything but `0`) means headless.
87: fn headless_requested() -> bool {
88:     match std::env::var(contract::HEADLESS_ENV) {
89:         Ok(value) => value != "0",
90:         Err(_) => false,
91:     }
92: }
93: 
94: /// Exit the process when the launcher writes `quit` on stdin.
95: ///
96: /// The launcher asks politely before it kills, and a game that ignored the line
97: /// would pay the full termination grace on every stop.  This is deliberately a
98: /// raw thread rather than a Bevy event: it must work in both the windowed and
99: /// the headless configuration, and it needs nothing from the ECS.
100: fn watch_stdin() {
101:     use std::io::BufRead;
102:     std::thread::spawn(|| {
103:         let stdin = std::io::stdin();
104:         for line in stdin.lock().lines() {
105:             match line {
106:                 Ok(line) if line.trim() == "quit" => std::process::exit(0),
107:                 Ok(_) => {}
108:                 // EOF: the launcher closed the pipe without asking us to stop.
109:                 Err(_) => break,
110:             }
111:         }
112:     });
113: }

