93: /// The jump's own edge: `true` while `jump_pressed` is being held, so a level
94: /// that stays true is one jump and not a trampoline.
95: #[derive(Component, Debug, Default)]
96: struct JumpLatch(bool);
97: 
98: /// A collectible coin. `taken` makes the pickup one-way: a coin that has been
99: /// collected can never be collected again, so `CoinCounter.coins` never
100: /// decreases.
101: #[derive(Component, Debug, Default)]
102: struct Coin {
103:     taken: bool,
