125: fn spawn_scene(mut commands: Commands) {
126:     // The static ground slab, below the surface line.
127:     commands.spawn((
128:         GroundSlab,
129:         Transform::from_xyz(0.0, GROUND_Y - GROUND_THICKNESS * 0.5, 0.0),
130:     ));
131: 
132:     // The player: the frozen marker, an engine `Transform`, the ground state and
133:     // the game's own private components. It starts standing on the ground.
134:     commands.spawn((
135:         Player,
136:         Transform::from_xyz(0.0, GROUND_Y, 0.0),
137:         Grounded::default(),
138:         Velocity::default(),
139:         JumpLatch::default(),
140:     ));
141: 
142:     // Two coins on the walkable ground, ahead of the spawn point.
143:     commands.spawn((Coin::default(), Transform::from_xyz(COIN_A_X, COIN_Y, 0.0)));
144:     commands.spawn((Coin::default(), Transform::from_xyz(COIN_B_X, COIN_Y, 0.0)));
145: 
146:     // The goal marker, further along the same continuous ground.
147:     commands.spawn((Goal, Transform::from_xyz(GOAL_X, GOAL_Y, 0.0)));
148: }
