201: /// The coins and the goal, resolved against the player's real position.
202: ///
203: /// A coin is picked up when the player's `Transform` overlaps the coin's
204: /// `Transform`; the goal is reached the same way. Both are one-way: a taken coin
205: /// is never restored and `WinFlag.won` is only ever written `true`.
206: fn collect_pickups(
207:     mut coins: ResMut<CoinCounter>,
208:     mut win: ResMut<WinFlag>,
209:     player: Query<&Transform, With<Player>>,
210:     mut pickups: Query<(&Transform, Option<&mut Coin>, Option<&Goal>), Without<Player>>,

1: //! Deterministic in-process simulation checks for the game's five behaviours
2: //! (PRD P1..P5).
3: //!
4: //! These are the Developer's self-tests, compiled only for `cargo test` and
5: //! never part of the shipped binary.  They drive the **real** systems declared
6: //! in [`crate::game`] on a bare `MinimalPlugins` app with a fixed 1/60 s
7: //! timestep, so the numbers they assert are the same numbers the observation
8: //! battery samples from the running game through the frozen contract surfaces.
9: //!
10: //! The point of each check is a *semantic* claim, not a pixel claim:
11: //!
12: //! * a held `move_dir` produces tens of pixels of displacement, and writing `0`
13: //!   stops the player dead (no residual velocity);
14: //! * a jump leaves the ground, rises, falls and lands back on the ground inside
15: //!   a second, and `Grounded.on_ground` is `true` before take-off and `false`
16: //!   while airborne;
17: //! * the coin counter goes 0 -> positive by walking, and never decreases;
18: //! * the win flag goes `false` -> `true` by walking, one-way, at a position the
19: //!   player actually stands at;
20: //! * `FrameCounter.frames` advances exactly once per `app.update()`.
21: 
22: #![cfg(test)]
23: 
24: use std::time::Duration;
25: 
26: use bevy::prelude::*;
27: use bevy::time::TimeUpdateStrategy;
28: 
29: use crate::contract::{CoinCounter, FrameCounter, Grounded, InputIntent, Player, WinFlag};
30: use crate::game::{self, GROUND_Y, MOVE_SPEED};
31: 
32: /// The fixed timestep every observation is taken at: the headless
33: /// `ScheduleRunnerPlugin` runs at 60 Hz, so this mirrors the real game.
34: const DT: f64 = 1.0 / 60.0;
35: 
36: /// A fresh app with the game installed, the contract resources initialised and
37: /// the scene already spawned.
38: fn new_app() -> App {
39:     let mut app = App::new();
40:     app.add_plugins(MinimalPlugins);
41:     app.insert_resource(TimeUpdateStrategy::ManualDuration(Duration::from_secs_f64(
42:         DT,
43:     )));
44:     app.init_resource::<CoinCounter>()
45:         .init_resource::<WinFlag>()
46:         .init_resource::<FrameCounter>()
47:         .init_resource::<InputIntent>();
48:     game::add(&mut app);
49:     // The first update runs `Startup`, which spawns the level.
50:     app.update();
51:     app
52: }
53: 
54: fn step(app: &mut App, frames: u32) {
55:     for _ in 0..frames {
56:         app.update();
57:     }
58: }
59: 
60: fn set_move(app: &mut App, dir: i32) {
61:     app.world_mut().resource_mut::<InputIntent>().move_dir = dir;
62: }
63: 
64: fn set_jump(app: &mut App, pressed: bool) {
65:     app.world_mut().resource_mut::<InputIntent>().jump_pressed = pressed;
66: }
67: 
68: fn player_pos(app: &mut App) -> Vec2 {
69:     let world = app.world_mut();
70:     let mut query = world.query_filtered::<&Transform, With<Player>>();
71:     let transform = query.iter(&*world).next().expect("player entity");
72:     Vec2::new(transform.translation.x, transform.translation.y)
73: }
74: 
75: fn on_ground(app: &mut App) -> bool {
76:     let world = app.world_mut();
77:     let mut query = world.query_filtered::<&Grounded, With<Player>>();
78:     query
79:         .iter(&*world)
80:         .next()
81:         .expect("player entity")
82:         .on_ground
83: }
84: 
85: fn coins(app: &mut App) -> i64 {
86:     app.world().resource::<CoinCounter>().coins
87: }
88: 
89: fn won(app: &mut App) -> bool {
90:     app.world().resource::<WinFlag>().won
91: }
92: 
93: fn frames(app: &mut App) -> u64 {
94:     app.world().resource::<FrameCounter>().frames
95: }
