97: #[test]
98: fn spawn_state_is_clean() {
99:     let mut app = new_app();
100:     assert_eq!(coins(&mut app), 0, "the counter starts at 0");
101:     assert!(!won(&mut app), "the win flag starts false");
102:     assert!(on_ground(&mut app), "the player starts standing");
103:     assert!(player_pos(&mut app).y == GROUND_Y, "the player starts on the ground");
104: }
105: 
106: #[test]
107: fn frame_counter_advances_once_per_update() {
108:     let mut app = new_app();
109:     let before = frames(&mut app);
110:     step(&mut app, 10);
111:     assert_eq!(frames(&mut app), before + 10);
112: }
113: 
114: #[test]
115: fn held_move_dir_moves_and_zero_stops() {
116:     let mut app = new_app();
117:     let start = player_pos(&mut app).x;
118: 
119:     // A held direction (the level stays where it was written) must move far:
120:     // 30 frames at 60 Hz is 0.5 s, i.e. ~100 px at MOVE_SPEED.
121:     set_move(&mut app, 1);
122:     step(&mut app, 30);
123:     let travelled = player_pos(&mut app).x - start;
124:     assert!(
125:         travelled > MOVE_SPEED * 0.25,
126:         "a held direction should travel tens of px, got {travelled}"
127:     );
128: 
129:     // Writing 0 is an immediate stop with no residual drift.
130:     set_move(&mut app, 0);
131:     let stopped_at = player_pos(&mut app).x;
132:     step(&mut app, 15);
133:     assert!(
134:         (player_pos(&mut app).x - stopped_at).abs() < 0.001,
135:         "0 must stop the player dead, got {}",
136:         player_pos(&mut app).x - stopped_at
137:     );
138: 
139:     // And the intent itself is not cleared by the game (level-triggered).
140:     assert_eq!(app.world().resource::<InputIntent>().move_dir, 0);
141:     set_move(&mut app, -1);
142:     step(&mut app, 10);
143:     assert!(
144:         player_pos(&mut app).x < stopped_at,
145:         "a negative direction must move left"
146:     );
147: }
148: 
149: #[test]
150: fn jump_rises_then_lands_and_reports_ground_state() {
151:     let mut app = new_app();
152:     assert!(on_ground(&mut app), "grounded before take-off");
153:     let y0 = player_pos(&mut app).y;
154: 
155:     set_jump(&mut app, true);
156:     let mut apex = y0;
157:     let mut saw_airborne = false;
158:     let mut frames_airborne = 0;
159:     // One second of frames is enough for the whole arc.
160:     for _ in 0..60 {
161:         app.update();
162:         let y = player_pos(&mut app).y;
163:         apex = apex.max(y);
164:         if !on_ground(&mut app) {
165:             saw_airborne = true;
166:             frames_airborne += 1;
167:         }
168:     }
169:     set_jump(&mut app, false);
170: 
171:     assert!(saw_airborne, "the jump must clear the ground state");
172:     assert!(frames_airborne > 5, "the arc must last more than a few frames");
173:     assert!(
174:         apex - y0 > 20.0,
175:         "the jump must visibly rise, apex offset {}",
176:         apex - y0
177:     );
178:     assert_eq!(player_pos(&mut app).y, y0, "the jump must land back");
179:     assert!(on_ground(&mut app), "grounded again after landing");
180: 
181:     // The latch: a still-held jump does not bounce a second time.
182:     let landed = player_pos(&mut app).y;
183:     set_jump(&mut app, true);
184:     step(&mut app, 30);
185:     assert_eq!(player_pos(&mut app).y, landed, "holding jump is one jump");
186:     set_jump(&mut app, false);
187: }
188: 
189: #[test]
190: fn walking_right_collects_a_coin_and_reaches_the_goal_one_way() {
191:     let mut app = new_app();
192:     set_move(&mut app, 1);
193: 
194:     let mut coin_frame: Option<u64> = None;
195:     let mut win_frame: Option<u64> = None;
196:     let mut win_pos = 0.0_f32;
197:     let mut previous = coins(&mut app);
198:     let mut monotone = true;
199: 
200:     for frame in 0..150u64 {
201:         app.update();
202:         let now = coins(&mut app);
203:         if now < previous {
204:             monotone = false;
205:         }
206:         previous = now;
207:         if now > 0 && coin_frame.is_none() {
208:             coin_frame = Some(frame);
209:         }
210:         if won(&mut app) && win_frame.is_none() {
211:             win_frame = Some(frame);
212:             win_pos = player_pos(&mut app).x;
213:         }
214:     }
215:     set_move(&mut app, 0);
216: 
217:     let coin_frame = coin_frame.expect("a walk to the right must collect a coin");
218:     let win_frame = win_frame.expect("a walk to the right must reach the goal");
219:     assert!(monotone, "the coin counter must never decrease");
220:     assert!(coins(&mut app) >= 1, "the counter must end positive");
221:     assert!(
222:         coin_frame <= win_frame,
223:         "the coin comes before the goal on the walk"
224:     );
225:     assert!(
226:         win_pos > 0.0,
227:         "the win frame's player x must be on the goal's side, got {win_pos}"
228:     );
229: 
230:     // One-way: walking back does not undo the win, and the counter holds.
231:     let banked = coins(&mut app);
232:     set_move(&mut app, -1);
233:     step(&mut app, 40);
234:     set_move(&mut app, 0);
235:     assert!(won(&mut app), "the win flag is one-way");
236:     assert_eq!(coins(&mut app), banked, "collected coins stay collected");
237: }

207:     mut coins: ResMut<CoinCounter>,
208:     mut win: ResMut<WinFlag>,
209:     player: Query<&Transform, With<Player>>,
210:     mut pickups: Query<(&Transform, Option<&mut Coin>, Option<&Goal>), Without<Player>>,
211: ) {
212:     for player_transform in &player {
213:         let px = player_transform.translation.x;
214:         let py = player_transform.translation.y;
215: 
216:         for (pickup_transform, coin, goal) in &mut pickups {
217:             let dx = (px - pickup_transform.translation.x).abs();
218:             let dy = (py - pickup_transform.translation.y).abs();
219:             if dy > PICKUP_HALF_HEIGHT {
220:                 continue;
221:             }
222: 
223:             if let Some(mut coin) = coin {
224:                 if dx <= COIN_HALF_WIDTH && !coin.taken {
225:                     coin.taken = true;
226:                     coins.coins = coins.coins.saturating_add(1);
227:                 }
228:             }
229: 
230:             if goal.is_some() && dx <= GOAL_HALF_WIDTH {
231:                 win.won = true;
232:             }
233:         }
234:     }
235: }

