150~/// The game's own clock (D297 (b)): every semantic tool reports this value as
151~/// `frame`, so it must advance exactly once per frame.
152~fn count_frames(mut counter: ResMut<FrameCounter>) {
153~    counter.frames = counter.frames.saturating_add(1);
154~}
155~
156~/// Turn the held intent into velocity, and consume the jump's edge.
157~///
158~/// `move_dir` is a level: the velocity is *derived* from it, never accumulated,
159~/// so `0` is an immediate stop with no residual motion. The jump is an edge: the
160~/// latch makes a held `jump_pressed` a single take-off.
161~fn apply_input(
162~    intent: Res<InputIntent>,
163~    mut player: Query<(&mut Velocity, &mut Grounded, &mut JumpLatch), With<Player>>,
164~) {
165~    for (mut velocity, mut grounded, mut latch) in &mut player {
166~        velocity.x = MOVE_SPEED * intent.move_dir as f32;
167~        if intent.jump_pressed && grounded.on_ground && !latch.0 {
168~            velocity.y = JUMP_SPEED;
169~            grounded.on_ground = false;
170~        }
171~        latch.0 = intent.jump_pressed;
172~    }
173~}
174~
175~/// Integrate one frame of motion and settle on the ground.
176~///
177~/// `Grounded.on_ground` is true exactly while the player's feet rest on the
178~/// surface: it is cleared on the take-off frame and only set again when the arc
179~/// comes back down, which is what the ground-state check samples before the
180~/// take-off.
181~fn integrate(
182~    time: Res<Time>,
183~    mut player: Query<(&mut Transform, &mut Velocity, &mut Grounded), With<Player>>,
184~) {
185~    let dt = time.delta_secs().min(MAX_STEP_SECONDS);
186~    for (mut transform, mut velocity, mut grounded) in &mut player {
187~        transform.translation.x = (transform.translation.x + velocity.x * dt)
188~            .clamp(-GROUND_HALF_WIDTH, GROUND_HALF_WIDTH);
189~        velocity.y -= GRAVITY * dt;
190~        transform.translation.y += velocity.y * dt;
191~        if transform.translation.y <= GROUND_Y {
192~            transform.translation.y = GROUND_Y;
193~            velocity.y = 0.0;
194~            grounded.on_ground = true;
195~        } else {
196~            grounded.on_ground = false;
197~        }
198~    }
199~}
