115:pub fn add(app: &mut App) {
116:    app.add_systems(Startup, spawn_scene);
117:    // The order matters: the clock ticks first, then the intent becomes motion,
118:    // then the world moves, then the world's consequences are recorded.
119:    app.add_systems(
120:        Update,
121:        (count_frames, apply_input, integrate, collect_pickups).chain(),
122:    );
123:}
