[206]fn collect_pickups(
[207]    mut coins: ResMut<CoinCounter>,
[208]    mut win: ResMut<WinFlag>,
[209]    player: Query<&Transform, With<Player>>,
[210]    mut pickups: Query<(&Transform, Option<&mut Coin>, Option<&Goal>), Without<Player>>,
[211]) {
