[94]/// Exit the process when the launcher writes `quit` on stdin.
[95]///
[96]/// The launcher asks politely before it kills, and a game that ignored the line
[97]/// would pay the full termination grace on every stop.  This is deliberately a
[98]/// raw thread rather than a Bevy event: it must work in both the windowed and
[99]/// the headless configuration, and it needs nothing from the ECS.
[100]fn watch_stdin() {
[101]    use std::io::BufRead;
[102]    std::thread::spawn(|| {
[103]        let stdin = std::io::stdin();
[104]        for line in stdin.lock().lines() {
[105]            match line {
[106]                Ok(line) if line.trim() == "quit" => std::process::exit(0),
[107]                Ok(_) => {}
[108]                // EOF: the launcher closed the pipe without asking us to stop.
[109]                Err(_) => break,
[110]            }
[111]        }
[112]    });
