[37]/// the scene already spawned.
[38]fn new_app() -> App {
[39]    let mut app = App::new();
[40]    app.add_plugins(MinimalPlugins);
[41]    app.insert_resource(TimeUpdateStrategy::ManualDuration(Duration::from_secs_f64(
[42]        DT,
[43]    )));
[44]    app.init_resource::<CoinCounter>()
[45]        .init_resource::<WinFlag>()
[46]        .init_resource::<FrameCounter>()
[47]        .init_resource::<InputIntent>();
[48]    game::add(&mut app);
[49]    // The first update runs `Startup`, which spawns the level.
[50]    app.update();
[51]    app
[52]}
