[149]#[test]
[150]fn jump_rises_then_lands_and_reports_ground_state() {
[151]    let mut app = new_app();
[152]    assert!(on_ground(&mut app), "grounded before take-off");
[153]    let y0 = player_pos(&mut app).y;
[154]
[155]    set_jump(&mut app, true);
[156]    let mut apex = y0;
[157]    let mut saw_airborne = false;
[158]    let mut frames_airborne = 0;
[159]    // One second of frames is enough for the whole arc.
[160]    for _ in 0..60 {
[161]        app.update();
[162]        let y = player_pos(&mut app).y;
[163]        apex = apex.max(y);
[164]        if !on_ground(&mut app) {
[165]            saw_airborne = true;
[166]            frames_airborne += 1;
[167]        }
[168]    }
[169]    set_jump(&mut app, false);
[170]
[171]    assert!(saw_airborne, "the jump must clear the ground state");
[172]    assert!(frames_airborne > 5, "the arc must last more than a few frames");
[173]    assert!(
[174]        apex - y0 > 20.0,
[175]        "the jump must visibly rise, apex offset {}",
[176]        apex - y0
[177]    );
[178]    assert_eq!(player_pos(&mut app).y, y0, "the jump must land back");
[179]    assert!(on_ground(&mut app), "grounded again after landing");
[180]
[181]    // The latch: a still-held jump does not bounce a second time.
[182]    let landed = player_pos(&mut app).y;
[183]    set_jump(&mut app, true);
[184]    step(&mut app, 30);
[185]    assert_eq!(player_pos(&mut app).y, landed, "holding jump is one jump");
[186]    set_jump(&mut app, false);
[187]}
