[189]#[test]
[190]fn walking_right_collects_a_coin_and_reaches_the_goal_one_way() {
[191]    let mut app = new_app();
[192]    set_move(&mut app, 1);
[193]
[194]    let mut coin_frame: Option<u64> = None;
[195]    let mut win_frame: Option<u64> = None;
[196]    let mut win_pos = 0.0_f32;
[197]    let mut previous = coins(&mut app);
[198]    let mut monotone = true;
[199]
[200]    for frame in 0..150u64 {
[201]        app.update();
[202]        let now = coins(&mut app);
[203]        if now < previous {
[204]            monotone = false;
[205]        }
[206]        previous = now;
[207]        if now > 0 && coin_frame.is_none() {
[208]            coin_frame = Some(frame);
[209]        }
[210]        if won(&mut app) && win_frame.is_none() {
[211]            win_frame = Some(frame);
[212]            win_pos = player_pos(&mut app).x;
[213]        }
[214]    }
[215]    set_move(&mut app, 0);
[216]
[217]    let coin_frame = coin_frame.expect("a walk to the right must collect a coin");
[218]    let win_frame = win_frame.expect("a walk to the right must reach the goal");
[219]    assert!(monotone, "the coin counter must never decrease");
[220]    assert!(coins(&mut app) >= 1, "the counter must end positive");
[221]    assert!(
[222]        coin_frame <= win_frame,
[223]        "the coin comes before the goal on the walk"
[224]    );
[225]    assert!(
[226]        win_pos > 0.0,
[227]        "the win frame's player x must be on the goal's side, got {win_pos}"
[228]    );
[229]
[230]    // One-way: walking back does not undo the win, and the counter holds.
[231]    let banked = coins(&mut app);
[232]    set_move(&mut app, -1);
[233]    step(&mut app, 40);
[234]    set_move(&mut app, 0);
[235]    assert!(won(&mut app), "the win flag is one-way");
[236]    assert_eq!(coins(&mut app), banked, "collected coins stay collected");
[237]}

